package com.kitchenos.connect.ui;

import android.app.Activity;
import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.view.*;
import android.widget.*;
import com.kitchenos.common.Ui;
import com.kitchenos.connect.kitchen.KitViews;
import java.math.BigDecimal;
import java.util.Locale;
import org.json.*;

/** Read-only recipe exploration. No cooking session, live controls or device connection. */
public final class StepPreviewDialog {
    private StepPreviewDialog() {}
    public static Dialog show(Activity activity,JSONObject recipe,int index,String cookLabel,Runnable cook){return show(activity,recipe,index,cookLabel,cook,new JSONArray());}
    public static Dialog show(Activity activity,JSONObject recipe,int index,String cookLabel,Runnable cook,JSONArray weighingHistory){
        JSONObject program=recipe.optJSONObject("machineProgram");JSONArray steps=program==null?null:program.optJSONArray("steps");
        if(steps==null||index<0||index>=steps.length())return null;
        JSONObject step=steps.optJSONObject(index);if(step==null)return null;
        Dialog dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);RotaryController knob=new RotaryController(activity,dialog::dismiss);
        LinearLayout surface=Ui.column(activity);surface.setBackground(KitViews.shape(activity,Ui.BG,24,0));surface.setPadding(dp(activity,24),dp(activity,18),dp(activity,24),dp(activity,18));dialog.setContentView(surface);
        LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView caption=text(activity,"Schritt "+(index+1)+" von "+steps.length()+" · Vorschau",19,Ui.MUTED,true);header.addView(caption,new LinearLayout.LayoutParams(0,-2,1));Button close=button(activity,knob,"Schließen",dialog::dismiss,false);close.setTag("step.preview.close");header.addView(close,new LinearLayout.LayoutParams(dp(activity,150),dp(activity,60)));surface.addView(header);gap(activity,surface,12);
        KitchenScroll scroll=new KitchenScroll(activity);LinearLayout content=Ui.column(activity);content.setPadding(0,0,0,dp(activity,18));scroll.addView(content);surface.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        ImageView art=new ImageView(activity);art.setScaleType(ImageView.ScaleType.FIT_CENTER);art.setBackground(KitViews.shape(activity,0xffe8ece6,20,0));art.setClipToOutline(true);art.setPadding(dp(activity,20),dp(activity,12),dp(activity,20),dp(activity,12));boolean machine="machine".equals(step.optString("kind"));art.setImageDrawable(new ApplianceVessel(machine?ApplianceVessel.Part.CLOSED_BOWL:ApplianceVessel.Part.BOWL,0));art.setContentDescription("Abbildung zu Schritt "+(index+1));if(machine)OemApplianceImages.apply(art,OemApplianceImages.Part.DEVICE);else if("weigh".equals(step.optString("kind")))OemApplianceImages.apply(art,OemApplianceImages.Part.BOWL);else StepImages.load(activity,art,recipe,index);content.addView(art,new LinearLayout.LayoutParams(-1,dp(activity,220)));gap(activity,content,18);
        LinearLayout reading=Ui.column(activity);reading.setTag("step.preview.reading");reading.addView(text(activity,step.optString("title"),29,Ui.INK,true));gap(activity,reading,10);TextView instruction=text(activity,step.optString("instruction"),23,Ui.INK,false);instruction.setLineSpacing(dp(activity,4),1);reading.addView(instruction);
        JSONArray ingredients=step.optJSONArray("ingredients");if(ingredients!=null&&ingredients.length()>0){gap(activity,reading,20);reading.addView(text(activity,"Zutaten in diesem Schritt",19,Ui.MUTED,true));for(int i=0;i<ingredients.length();i++){JSONObject item=ingredients.optJSONObject(i);if(item==null)continue;LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);ImageView portrait=new ImageView(activity);portrait.setScaleType(ImageView.ScaleType.FIT_CENTER);IngredientPortraits.bind(activity,portrait,item.optString("name"));row.addView(portrait,new LinearLayout.LayoutParams(dp(activity,66),dp(activity,66)));JSONObject measured=RecipeWeighingHistory.find(weighingHistory,step.optString("id")+":"+item.optString("name"));String previous=measured==null?"":"\nZuletzt eingewogen: "+measured.optInt("grams")+" g";TextView name=text(activity,item.optString("name")+previous+(item.optString("preparation").isEmpty()?"":"\n"+item.optString("preparation")),20,Ui.INK,false);LinearLayout.LayoutParams copy=new LinearLayout.LayoutParams(0,-2,1);copy.leftMargin=dp(activity,14);copy.rightMargin=dp(activity,12);row.addView(name,copy);row.addView(text(activity,amount(item),20,Ui.INK,true));reading.addView(row);}}
        JSONObject settings=step.optJSONObject("settings");if(settings!=null&&(machine||!settings.isNull("durationSeconds"))){LinearLayout params=new LinearLayout(activity);String[][] values=machine?new String[][]{{"Dauer",duration(settings)},{"Temperatur",settings.isNull("temperatureC")?"—":settings.optInt("temperatureC")==0?"Aus":settings.optInt("temperatureC")+" °C"},{"Rührstufe",settings.isNull("speedLevel")?"—":BigDecimal.valueOf(settings.optDouble("speedLevel",0)).stripTrailingZeros().toPlainString()}}:new String[][]{{"Dauer",duration(settings)}};for(String[] value:values){LinearLayout cell=Ui.column(activity);cell.setGravity(Gravity.CENTER);cell.setPadding(dp(activity,8),dp(activity,16),dp(activity,8),dp(activity,16));cell.setBackground(KitViews.shape(activity,Ui.CARD,18,0));cell.addView(text(activity,value[1],25,Ui.INK,true));cell.addView(text(activity,value[0],16,Ui.MUTED,false));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(dp(activity,3),0,dp(activity,3),0);params.addView(cell,cp);}gap(activity,reading,20);reading.addView(params);if(machine)reading.addView(text(activity,"counterclockwise".equals(settings.optString("direction"))?"Rühren":"Häckseln",17,Ui.MUTED,false));}
        content.addView(reading);ReadingRegion reader=knob.addReadingRegion(reading,scroll);content.addView(reader.hintView());gap(activity,surface,10);Button begin=button(activity,knob,cookLabel,()->{dialog.dismiss();cook.run();},true);begin.setTag("step.preview.cook");surface.addView(begin,new LinearLayout.LayoutParams(-1,dp(activity,66)));
        com.kitchenos.connect.ui.C3RotaryBroadcast.bind(dialog.getWindow());dialog.setOnKeyListener((d,key,event)->knob.dispatch(event));surface.setOnGenericMotionListener((v,event)->knob.motion(event));dialog.setOnDismissListener(d->knob.reset());dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-dp(activity,32),dp(activity,920)),activity.getResources().getDisplayMetrics().heightPixels-dp(activity,32));dialog.getWindow().getDecorView().setSystemUiVisibility(activity.getWindow().getDecorView().getSystemUiVisibility());}return dialog;
    }
    private static Button button(Activity activity,RotaryController knob,String label,Runnable action,boolean primary){Button b=Ui.button(activity,label,v->action.run());b.setTextSize(20);b.setContentDescription(label);b.setMinimumHeight(dp(activity,60));b.setBackground(KitViews.shape(activity,primary?Ui.ACCENT:Ui.CARD,16,0));b.setTextColor(primary?0xff171716:Ui.INK);knob.add(b);return b;}
    private static TextView text(Activity a,String value,int size,int color,boolean bold){return KitViews.text(a,value,size,color,bold);}
    private static int dp(Activity a,int value){return Ui.dp(a,value);}
    private static void gap(Activity a,LinearLayout parent,int height){parent.addView(new View(a),new LinearLayout.LayoutParams(1,dp(a,height)));}
    private static String amount(JSONObject item){Object amount=item.opt("amount");return amount instanceof Number?new BigDecimal(amount.toString()).stripTrailingZeros().toPlainString()+" "+item.optString("unit"):"Menge offen";}
    private static String duration(JSONObject settings){if(settings.isNull("durationSeconds"))return "—";int seconds=settings.optInt("durationSeconds",0);return seconds>=60?String.format(Locale.GERMAN,"%d:%02d min",seconds/60,seconds%60):seconds+" s";}
}
